   () => {
    return gulp.src(["./dist/*.html"], { read: false }).pipe(cleaner());
  }
));
    // ...
function cleaner() {
  return through.obj(function (file, enc, cb) {
    rimraf(
      path.resolve(file.cwd || process.cwd(), file.path),
      function (err) {
        if (err) {
          this.emit("error", new gutil.PluginError("Cleanup old files", err));
        }
        this.push(file);
        cb();
      }.bind(this)
    );
  });
}

